{
  "definition_simple": "To get excited, lively, or enthusiastic.",
  "definition_standard": "To swell, rise up, or figuratively, to become lively, excited, or enthusiastic (e.g., at a party or event).",
  "examples": [
    {
      "japanese": "パーティーがだんだん盛り上がってきた。",
      "romaji": "Paatii ga dandan moriagatte kita.",
      "english": "The party is gradually getting lively."
    },
    {
      "japanese": "ライブの終盤で会場の雰囲気が最高潮に盛り上がった。",
      "romaji": "Raibu no shuban de kaijou no fun'iki ga saikouchou ni moriagatta.",
      "english": "The atmosphere at the venue reached a fever pitch toward the end of the live show."
    },
    {
      "japanese": "そのニュースを聞いて、クラス中が盛り上がった。",
      "romaji": "Sono nyuusu o kiite, kurasu-chuu ga moriagatta.",
      "english": "Hearing that news got the whole class excited."
    }
  ]
}
